import React from 'react';
import './HomePage.css';
import UpMenu from './UpMenu/UpMenu';
import LeftMenu from './LeftMenu/LeftMenu';
import UserStatus from './TheFeed/UserStatus';
import RightMenu from './RightMenu/RightMenu';
import Posts from './TheFeed/Posts';
import posts from "./data/db.json";
import { useState } from 'react';

function HomePage() {
    const [postsList,setPostsList] = useState(posts);

    const likePost =(id, numLikes) =>{
        const postIndex= postsList.findIndex(post=>post.id===id);
        postsList[postIndex].like+=numLikes;
        setPostsList([...postsList]);
    }

    const deletePost = (id) => {
        const postIndex= postsList.findIndex(post=>post.id===id);
        postsList.splice(postIndex,1);
        setPostsList([...postsList]);
    }

     
     return (
         <div class="container- fluid">
             <div class="row upfeed">
                 <UpMenu />
             </div>
             <div class="row feed">
             <div class="col-3 bg-light ">
                 <LeftMenu />
                 </div>
                 <div class="row col-6">
                     <UserStatus setPostsList={setPostsList} postsList={postsList} />
                     {postsList.map((post)=>
                     <Posts {...post} onLike={(likeCount)=>likePost(post.id, likeCount)} onDelete={()=>deletePost(post.id)}/>
                     )}
                 </div>
                 <div class="col-3 bg-light">
                     <RightMenu/>
                 </div>
             </div>
         </div>
     );
 }

 export default HomePage;
